parameters.jsCode:
// Une los datos de la HU con el análisis de Gemini. Si la IA falló, igual se notifica.
const body = $('Webhook BA Flow').first().json.body;
let analisis = { riesgo: 'Sin análisis', resumen: 'No se pudo analizar la historia con IA.', observaciones: [] };
try {
  const texto = $input.first().json.candidates[0].content.parts[0].text;
  analisis = JSON.parse(texto);
} catch (e) {}
const obs = Array.isArray(analisis.observaciones) ? analisis.observaciones : [];
return [{ json: { ...body, ...analisis, observaciones_texto: obs.map((o) => '• ' + o).join('\n') || '—' } }];

